CREATE TABLE "customer" ("id" INTEGER PRIMARY KEY, "customer_name" TEXT, "segment_id" INTEGER, "created_at" TEXT, FOREIGN KEY("segment_id") REFERENCES "customer_segment"("id"));
CREATE TABLE "customer_segment" ("id" INTEGER PRIMARY KEY, "segment_name" TEXT, "created_at" TEXT);
CREATE TABLE "customer_contact" ("id" INTEGER PRIMARY KEY, "customer_id" INTEGER, "contact_name" TEXT, "created_at" TEXT, FOREIGN KEY("customer_id") REFERENCES "customer"("id"));
CREATE TABLE "customer_address" ("id" INTEGER PRIMARY KEY, "customer_id" INTEGER, "address_text" TEXT, "created_at" TEXT, FOREIGN KEY("customer_id") REFERENCES "customer"("id"));
CREATE TABLE "product_category" ("id" INTEGER PRIMARY KEY, "category_name" TEXT, "created_at" TEXT);
CREATE TABLE "product" ("id" INTEGER PRIMARY KEY, "category_id" INTEGER, "product_name" TEXT, "unit_price" NUMERIC, "created_at" TEXT, FOREIGN KEY("category_id") REFERENCES "product_category"("id"));
CREATE TABLE "warehouse" ("id" INTEGER PRIMARY KEY, "warehouse_name" TEXT, "created_at" TEXT);
CREATE TABLE "quotation" ("id" INTEGER PRIMARY KEY, "customer_id" INTEGER, "quoted_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("customer_id") REFERENCES "customer"("id"));
CREATE TABLE "quotation_line" ("id" INTEGER PRIMARY KEY, "quotation_id" INTEGER, "product_id" INTEGER, "quantity" NUMERIC, "created_at" TEXT, FOREIGN KEY("quotation_id") REFERENCES "quotation"("id"), FOREIGN KEY("product_id") REFERENCES "product"("id"));
CREATE TABLE "sales_order" ("id" INTEGER PRIMARY KEY, "customer_id" INTEGER, "quotation_id" INTEGER, "order_amount" NUMERIC, "order_status" TEXT, "created_at" TEXT, FOREIGN KEY("customer_id") REFERENCES "customer"("id"), FOREIGN KEY("quotation_id") REFERENCES "quotation"("id"));
CREATE TABLE "sales_order_history" ("id" INTEGER PRIMARY KEY, "original_order_id" INTEGER, "customer_id" INTEGER, "order_amount" NUMERIC, "archived_at" TEXT, "created_at" TEXT, FOREIGN KEY("original_order_id") REFERENCES "sales_order"("id"), FOREIGN KEY("customer_id") REFERENCES "customer"("id"));
CREATE TABLE "sales_order_line" ("id" INTEGER PRIMARY KEY, "order_id" INTEGER, "product_id" INTEGER, "quantity" NUMERIC, "line_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("order_id") REFERENCES "sales_order"("id"), FOREIGN KEY("product_id") REFERENCES "product"("id"));
CREATE TABLE "sales_order_line_history" ("id" INTEGER PRIMARY KEY, "history_id" INTEGER, "product_id" INTEGER, "quantity" NUMERIC, "created_at" TEXT, FOREIGN KEY("history_id") REFERENCES "sales_order_history"("id"), FOREIGN KEY("product_id") REFERENCES "product"("id"));
CREATE TABLE "sales_order_daily_summary" ("id" INTEGER PRIMARY KEY, "customer_id" INTEGER, "business_date" TEXT, "order_count" INTEGER, "order_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("customer_id") REFERENCES "customer"("id"));
CREATE TABLE "sales_order_monthly_summary" ("id" INTEGER PRIMARY KEY, "customer_id" INTEGER, "business_month" TEXT, "order_count" INTEGER, "order_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("customer_id") REFERENCES "customer"("id"));
CREATE TABLE "shipment" ("id" INTEGER PRIMARY KEY, "order_id" INTEGER, "warehouse_id" INTEGER, "shipped_at" TEXT, "created_at" TEXT, FOREIGN KEY("order_id") REFERENCES "sales_order"("id"), FOREIGN KEY("warehouse_id") REFERENCES "warehouse"("id"));
CREATE TABLE "shipment_line" ("id" INTEGER PRIMARY KEY, "shipment_id" INTEGER, "order_line_id" INTEGER, "shipped_quantity" NUMERIC, "created_at" TEXT, FOREIGN KEY("shipment_id") REFERENCES "shipment"("id"), FOREIGN KEY("order_line_id") REFERENCES "sales_order_line"("id"));
CREATE TABLE "shipment_tracking" ("id" INTEGER PRIMARY KEY, "shipment_id" INTEGER, "event_time" TEXT, "event_text" TEXT, "created_at" TEXT, FOREIGN KEY("shipment_id") REFERENCES "shipment"("id"));
CREATE TABLE "sales_return" ("id" INTEGER PRIMARY KEY, "order_id" INTEGER, "customer_id" INTEGER, "return_reason" TEXT, "created_at" TEXT, FOREIGN KEY("order_id") REFERENCES "sales_order"("id"), FOREIGN KEY("customer_id") REFERENCES "customer"("id"));
CREATE TABLE "sales_return_line" ("id" INTEGER PRIMARY KEY, "return_id" INTEGER, "product_id" INTEGER, "returned_quantity" NUMERIC, "created_at" TEXT, FOREIGN KEY("return_id") REFERENCES "sales_return"("id"), FOREIGN KEY("product_id") REFERENCES "product"("id"));
CREATE TABLE "invoice" ("id" INTEGER PRIMARY KEY, "order_id" INTEGER, "customer_id" INTEGER, "invoiced_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("order_id") REFERENCES "sales_order"("id"), FOREIGN KEY("customer_id") REFERENCES "customer"("id"));
CREATE TABLE "invoice_line" ("id" INTEGER PRIMARY KEY, "invoice_id" INTEGER, "order_line_id" INTEGER, "tax_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("invoice_id") REFERENCES "invoice"("id"), FOREIGN KEY("order_line_id") REFERENCES "sales_order_line"("id"));
CREATE TABLE "credit_note" ("id" INTEGER PRIMARY KEY, "invoice_id" INTEGER, "return_id" INTEGER, "credit_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("invoice_id") REFERENCES "invoice"("id"), FOREIGN KEY("return_id") REFERENCES "sales_return"("id"));
CREATE TABLE "receivable" ("id" INTEGER PRIMARY KEY, "invoice_id" INTEGER, "customer_id" INTEGER, "receivable_amount" NUMERIC, "due_date" TEXT, "created_at" TEXT, FOREIGN KEY("invoice_id") REFERENCES "invoice"("id"), FOREIGN KEY("customer_id") REFERENCES "customer"("id"));
CREATE TABLE "receivable_installment" ("id" INTEGER PRIMARY KEY, "receivable_id" INTEGER, "due_date" TEXT, "installment_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("receivable_id") REFERENCES "receivable"("id"));
CREATE TABLE "receipt" ("id" INTEGER PRIMARY KEY, "customer_id" INTEGER, "received_amount" NUMERIC, "received_at" TEXT, "created_at" TEXT, FOREIGN KEY("customer_id") REFERENCES "customer"("id"));
CREATE TABLE "receipt_allocation" ("id" INTEGER PRIMARY KEY, "receipt_id" INTEGER, "receivable_id" INTEGER, "allocated_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("receipt_id") REFERENCES "receipt"("id"), FOREIGN KEY("receivable_id") REFERENCES "receivable"("id"));
CREATE TABLE "refund" ("id" INTEGER PRIMARY KEY, "return_id" INTEGER, "customer_id" INTEGER, "refund_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("return_id") REFERENCES "sales_return"("id"), FOREIGN KEY("customer_id") REFERENCES "customer"("id"));
CREATE TABLE "refund_allocation" ("id" INTEGER PRIMARY KEY, "refund_id" INTEGER, "receipt_id" INTEGER, "allocated_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("refund_id") REFERENCES "refund"("id"), FOREIGN KEY("receipt_id") REFERENCES "receipt"("id"));
CREATE TABLE "inventory_balance" ("id" INTEGER PRIMARY KEY, "warehouse_id" INTEGER, "product_id" INTEGER, "on_hand_quantity" NUMERIC, "created_at" TEXT, FOREIGN KEY("warehouse_id") REFERENCES "warehouse"("id"), FOREIGN KEY("product_id") REFERENCES "product"("id"));
CREATE TABLE "inventory_movement" ("id" INTEGER PRIMARY KEY, "warehouse_id" INTEGER, "product_id" INTEGER, "movement_quantity" NUMERIC, "created_at" TEXT, FOREIGN KEY("warehouse_id") REFERENCES "warehouse"("id"), FOREIGN KEY("product_id") REFERENCES "product"("id"));
CREATE TABLE "stock_reservation" ("id" INTEGER PRIMARY KEY, "order_line_id" INTEGER, "warehouse_id" INTEGER, "reserved_quantity" NUMERIC, "created_at" TEXT, FOREIGN KEY("order_line_id") REFERENCES "sales_order_line"("id"), FOREIGN KEY("warehouse_id") REFERENCES "warehouse"("id"));
CREATE TABLE "supplier" ("id" INTEGER PRIMARY KEY, "supplier_name" TEXT, "created_at" TEXT);
CREATE TABLE "purchase_order" ("id" INTEGER PRIMARY KEY, "supplier_id" INTEGER, "purchase_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("supplier_id") REFERENCES "supplier"("id"));
CREATE TABLE "purchase_order_line" ("id" INTEGER PRIMARY KEY, "purchase_id" INTEGER, "product_id" INTEGER, "quantity" NUMERIC, "created_at" TEXT, FOREIGN KEY("purchase_id") REFERENCES "purchase_order"("id"), FOREIGN KEY("product_id") REFERENCES "product"("id"));
CREATE TABLE "goods_receipt" ("id" INTEGER PRIMARY KEY, "purchase_id" INTEGER, "warehouse_id" INTEGER, "received_at" TEXT, "created_at" TEXT, FOREIGN KEY("purchase_id") REFERENCES "purchase_order"("id"), FOREIGN KEY("warehouse_id") REFERENCES "warehouse"("id"));
CREATE TABLE "goods_receipt_line" ("id" INTEGER PRIMARY KEY, "goods_receipt_id" INTEGER, "purchase_line_id" INTEGER, "quantity" NUMERIC, "created_at" TEXT, FOREIGN KEY("goods_receipt_id") REFERENCES "goods_receipt"("id"), FOREIGN KEY("purchase_line_id") REFERENCES "purchase_order_line"("id"));
CREATE TABLE "payable" ("id" INTEGER PRIMARY KEY, "purchase_id" INTEGER, "supplier_id" INTEGER, "payable_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("purchase_id") REFERENCES "purchase_order"("id"), FOREIGN KEY("supplier_id") REFERENCES "supplier"("id"));
CREATE TABLE "payment" ("id" INTEGER PRIMARY KEY, "payable_id" INTEGER, "supplier_id" INTEGER, "paid_amount" NUMERIC, "created_at" TEXT, FOREIGN KEY("payable_id") REFERENCES "payable"("id"), FOREIGN KEY("supplier_id") REFERENCES "supplier"("id"));
